// 1. Valida o Status Code HTTP da resposta
pm.test("Status code is 200", function () {
  pm.response.to.have.status(200);
});

// 2. Valida o tempo de resposta (SLA básico de performance)
pm.test("Response time is less than 2000ms", function () {
  pm.expect(pm.response.responseTime).to.be.below(2000);
});

// 3. Converte o corpo da resposta para JSON e valida o contrato/regras
const jsonData = pm.response.json();

pm.test("Contrato JSON deve conter 'responseCode' e lista de produtos", function () {
    pm.expect(jsonData).to.have.property("responseCode", 200);
    pm.expect(jsonData).to.have.property("products");
    pm.expect(jsonData.products).to.be.an("array").that.is.not.empty;
});

// 4. Valida os atributos do primeiro item retornado
pm.test("Primeiro produto deve conter id, name e price", function () {
    const firstProduct = jsonData.products[0];
    pm.expect(firstProduct).to.have.all.keys("id", "name", "price", "brand", "category");
});

// 1. Valida que o servidor respondeu à requisição HTTP
pm.test("Status Code HTTP deve ser 200", function () {
    pm.response.to.have.status(200);
});

// 2. Valida o contrato e o código de erro interno da API (405 Method Not Allowed)
const jsonData = pm.response.json();

pm.test("Corpo JSON deve retornar responseCode 405", function () {
    pm.expect(jsonData).to.have.property("responseCode", 405);
});

pm.test("Mensagem de erro deve informar que o método não é suportado", function () {
    pm.expect(jsonData).to.have.property("message", "This request method is not supported.");
});

// 1. Valida o Status Code HTTP
pm.test("Status Code HTTP deve ser 200", function () {
    pm.response.to.have.status(200);
});

const jsonData = pm.response.json();

// 2. Valida o código de sucesso interno e se a lista de produtos não veio vazia
pm.test("Deve retornar responseCode 200 e lista de produtos encontrada", function () {
    pm.expect(jsonData).to.have.property("responseCode", 200);
    pm.expect(jsonData.products).to.be.an("array").that.is.not.empty;
});

// 3. Valida regra de negócio: os produtos retornados correspondem ao termo buscado ("top")
pm.test("Resultados devem conter o termo buscado no nome ou categoria", function () {
    const firstProduct = jsonData.products[0];
    const matchName = firstProduct.name.toLowerCase().includes("top");
    const matchCategory = firstProduct.category.category.toLowerCase().includes("top");
    
    pm.expect(matchName || matchCategory).to.be.true;
});

// 1. Valida que o servidor respondeu à requisição HTTP
pm.test("Status Code HTTP deve ser 200", function () {
    pm.response.to.have.status(200);
});

const jsonData = pm.response.json();

// 2. Valida o código de negócio 404 (Usuário não encontrado)
pm.test("Corpo JSON deve retornar responseCode 404", function () {
    pm.expect(jsonData).to.have.property("responseCode", 404);
});

// 3. Valida a mensagem exata de falha de autenticação
pm.test("Mensagem deve informar 'User not found!'", function () {
    pm.expect(jsonData).to.have.property("message", "User not found!");
});
